import z3

def solve():
    n = 17
    solver = z3.Solver()

    # Variables
    E = [[None for _ in range(n)] for _ in range(n)]
    for i in range(n):
        for j in range(i + 1, n):
            E[i][j] = z3.Bool(f"E_{i}_{j}")
            E[j][i] = E[i][j]

    # Triangle-free
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                solver.add(z3.Or(z3.Not(E[i][j]), z3.Not(E[j][k]), z3.Not(E[i][k])))

    # Maximal (diameter 2)
    for i in range(n):
        for j in range(i + 1, n):
            # If not E[i][j], they must share a neighbor
            shared_neighbor = []
            for k in range(n):
                if k != i and k != j:
                    shared_neighbor.append(z3.And(E[i][k], E[j][k]))
            solver.add(z3.Or(E[i][j], z3.Or(shared_neighbor)))

    # Fixed edges
    fixed_edges = [(0,15), (3,15), (6,15), (9,15), (11,15), (14,16)]
    for u, v in fixed_edges:
        if u > v:
            u, v = v, u
        solver.add(E[u][v] == True)

    if solver.check() == z3.sat:
        m = solver.model()
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if z3.is_true(m[E[i][j]]):
                    edges.extend([i, j])
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()

from pysat.solvers import Glucose3

def solve():
    n = 17
    solver = Glucose3()

    def var(i, j):
        if i > j:
            i, j = j, i
        # i from 0 to 15, j from i+1 to 16
        # index = i * 17 - i*(i+1)//2 + j - i - 1 + 1
        # Let's just use a dictionary or simple array
        return i * n + j + 1

    # Triangle-free
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                solver.add_clause([-var(i, j), -var(j, k), -var(i, k)])

    # Maximal
    aux_var_start = n * n + 1
    aux_var_idx = aux_var_start

    for i in range(n):
        for j in range(i + 1, n):
            clause = [var(i, j)]
            for k in range(n):
                if k != i and k != j:
                    # A_{i, j, k} <=> E_ik and E_jk
                    a_var = aux_var_idx
                    aux_var_idx += 1

                    solver.add_clause([-a_var, var(i, k)])
                    solver.add_clause([-a_var, var(j, k)])
                    solver.add_clause([-var(i, k), -var(j, k), a_var])

                    clause.append(a_var)
            solver.add_clause(clause)

    # Fixed edges
    fixed_edges = [(0,15), (3,15), (6,15), (9,15), (11,15), (14,16)]
    for u, v in fixed_edges:
        solver.add_clause([var(u, v)])

    if solver.solve():
        model = solver.get_model()
        edges = []
        for i in range(n):
            for j in range(i + 1, n):
                if model[var(i, j) - 1] > 0:
                    edges.extend([i, j])
        print("SAT")
        print(edges)
    else:
        print("UNSAT")

solve()
